<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{Plus,Search}from'lucide-vue-next';import ModalDialog from'@/components/ModalDialog.vue';import StatusBadge from'@/components/StatusBadge.vue';import EmptyState from'@/components/EmptyState.vue';import{api}from'@/services/api';import{errorMessage}from'@/services/http';import type{Station}from'@/types';const items=ref<Station[]>([]),keyword=ref(''),open=ref(false),message=ref('');const form=reactive({code:'',name:'',city:''});async function load(){try{items.value=await api.adminStations(keyword.value)}catch(e){message.value=errorMessage(e)}}async function add(){try{await api.createStation(form);open.value=false;Object.assign(form,{code:'',name:'',city:''});await load()}catch(e){message.value=errorMessage(e)}}async function toggle(i:Station){try{await api.stationStatus(i.id,i.status?0:1);await load()}catch(e){message.value=errorMessage(e)}}onMounted(load)
</script>
<template><section class="admin-page"><header class="page-head"><div><p class="eyebrow">STATIONS</p><h1>车站管理</h1><p>维护可用于路线编排的铁路车站</p></div><button class="btn primary" @click="open=true"><Plus/>新增车站</button></header><div class="toolbar"><label class="search-input"><Search/><input v-model="keyword" placeholder="搜索车站编码、名称或城市" @keyup.enter="load"></label><button class="btn ghost" @click="load">搜索</button></div><p v-if="message" class="notice error">{{message}}</p><div v-if="items.length" class="data-table-wrap"><table class="data-table"><thead><tr><th>车站编码</th><th>车站名称</th><th>所在城市</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="i in items" :key="i.id"><td><code>{{i.code}}</code></td><td><strong>{{i.name}}</strong></td><td>{{i.city}}</td><td><StatusBadge :active="i.status===1"/></td><td><button class="link-btn" @click="toggle(i)">{{i.status?'停用':'启用'}}</button></td></tr></tbody></table></div><EmptyState v-else/><ModalDialog :open="open" title="新增车站" @close="open=false"><form class="stack-form" @submit.prevent="add"><label>车站编码<input v-model.trim="form.code" required maxlength="10" placeholder="如 BJP"></label><label>车站名称<input v-model.trim="form.name" required maxlength="64" placeholder="如 北京南站"></label><label>所在城市<input v-model.trim="form.city" required maxlength="64" placeholder="如 北京"></label><button class="btn primary wide">保存车站</button></form></ModalDialog></section></template>
